def solve(g):
    H,W=len(g),len(g[0])
    one=tw=None
    for i in range(H):
        for j in range(W):
            if g[i][j]==1: one=(i,j)
            if g[i][j]==2: tw=(i,j)
    out=[row[:] for row in g]
    dr=(tw[0]>one[0])-(tw[0]<one[0]); dc=(tw[1]>one[1])-(tw[1]<one[1])
    i,j=one
    while True:
        i+=dr; j+=dc; out[i][j]=3
        if abs(i-tw[0])==1 or abs(j-tw[1])==1: break
    if abs(i-tw[0])>1:
        while abs(i-tw[0])>1: i+=dr; out[i][j]=3
    else:
        while abs(j-tw[1])>1: j+=dc; out[i][j]=3
    return out

